    public Quadrat(int pSeite) {
        super(pSeite, pSeite);
    }

    /** Ein Quadrat bleibt ein Quadrat: Beide Seiten ändern sich mit. */
    public void setBreite(int pBreite) {
        breite = pBreite;
        hoehe = pBreite;
    }

    /** Ebenso. */
